  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--panel);
}

tbody tr:nth-child(even) {
  background: #f8fafc;
}

tbody tr:hover {
  background: #f1f5f9;
}

/* ==================== SEMANTIC COLORS ==================== */

.red { color: var(--red); }
.green { color: var(--green); }

