  .content-grid > *,
  .content-grid.wide > *,
  .financial-snapshot-grid > * {
    min-width: 0;
  }

  .trend-chart {
    height: 260px;
  }

  .panel-heading {
    flex-direction: column;
    gap: 8px;
  }
}

@media (max-width: 520px) {
  .metric-strip,
  .metric-strip.metrics-7 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
