  .metric-strip.four-col {
    grid-template-columns: 1fr;
  }

  .mini-metric-grid {
    grid-template-columns: 1fr;
  }

  .quality-facts {
    grid-template-columns: 1fr;
  }

  .mini-metric-grid > * {
    min-width: 0;
  }

  .chart-panel,
  .data-panel {
