        <line x1="60" y1="350" x2="780" y2="350" className="axis" />
        <line x1="60" y1="30" x2="780" y2="30" className="axis muted" />
        <line x1="60" y1="110" x2="780" y2="110" className="axis grid" />
        <line x1="60" y1="190" x2="780" y2="190" className="axis grid" />
