:root {
  color-scheme: light;
  --bg: #f2f3f7;
  --ink: #1a1e2b;
  --muted: #5f6b7f;
  --line: #d8dce6;
  --line-light: #e9ecf2;
  --panel: #ffffff;
  --red: #d9363e;
  --green: #0e9d5d;
  --blue: #2b6de5;
  --gold: #b88719;
  --purple: #7c3aed;
  --teal: #0f8f88;
  --amber-bg: #fff8e5;
  --red-bg: #fef2f2;
  --green-bg: #f0fdf4;
  --blue-bg: #eef4ff;
  --surface-1: #f7f8fb;
  --surface-2: #fafbfd;
  --shadow-sm: 0 1px 2px rgba(15,23,42,0.04);
  --shadow-md: 0 4px 12px rgba(15,23,42,0.06);
  --red-fill: #fef0ef;
  --green-fill: #edf9f2;
  --volume-up-fill: #f2c4c0;
  --volume-down-fill: #b0e0c6;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI",
    "PingFang SC", "Microsoft YaHei",
    "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-variant-numeric: tabular-nums;
}

button,
input,
select,
textarea {
  font: inherit;
}

/* ==================== SHELL ==================== */

.dashboard-shell {
  width: min(1360px, calc(100vw - 40px));
  margin: 0 auto;
  padding: 24px 0 56px;
}

.hero-panel {
  margin-bottom: 16px;
  padding: 20px;
  border: 1px solid rgba(43, 109, 229, 0.16);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(247, 250, 255, 0.98)),
    var(--panel);
  box-shadow: var(--shadow-md);
}

.eyebrow {
  display: inline-flex;
  width: fit-content;
  margin: 0 0 4px;
  padding: 4px 9px;
  border: 1px solid rgba(43, 109, 229, 0.18);
  border-radius: 999px;
  color: var(--blue);
  background: rgba(43, 109, 229, 0.08);
  font-size: 13px;
  font-weight: 700;
}

/* ==================== TOP BAR ==================== */

.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0;
  margin-bottom: 12px;
  font-size: 13px;
  color: var(--muted);
}

.top-bar .freshness {
  display: flex;
  align-items: center;
  gap: 6px;
}

.top-bar .freshness::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
}

/* ==================== PRICE HEADER ==================== */

.price-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 4px;
}

.price-header .id-area {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.price-header .id-area .name {
  font-size: clamp(34px, 4vw, 52px);
  font-weight: 900;
  line-height: 1;
  word-break: break-word;
}

.price-header .id-area .symbol {
  font-size: 15px;
  color: var(--muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.price-header .quote-area {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px 10px;
  flex-shrink: 0;
  text-align: right;
  max-width: 520px;
}

.price-header .quote-area .price {
  font-size: clamp(36px, 4.2vw, 58px);
  font-weight: 900;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0;
  line-height: 1;
  white-space: nowrap;
}

.price-header .quote-area .price.is-missing {
  font-size: clamp(22px, 2.2vw, 30px);
  color: var(--muted);
  font-family: inherit;
}

.price-header .quote-area .change {
  font-size: 16px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  color: #fff;
}

.price-header .quote-area .change.up {
  background: var(--red);
}

.price-header .quote-area .change.down {
  background: var(--green);
}

.price-header .quote-area .change.neutral {
  color: var(--muted);
  background: var(--surface-1);
  border: 1px solid var(--line);
}

.quote-note {
  width: 100%;
  color: var(--muted);
  font-size: 13px;
}

/* ==================== META ROW ==================== */

.meta-row {
  display: grid;
  grid-template-columns: repeat(6, minmax(110px, 1fr)) auto;
  align-items: stretch;
  gap: 10px;
  margin: 16px 0 0;
}

.meta-row .meta-item {
  display: grid;
  gap: 7px;
  min-height: 70px;
  padding: 12px;
  border: 1px solid rgba(216, 220, 230, 0.9);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.74);
  font-size: 14px;
}

.meta-row .meta-item .meta-label {
  color: var(--muted);
}

.meta-row .meta-item .meta-value {
  font-weight: 600;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 18px;
  overflow-wrap: anywhere;
}

.insight-strip {
  display: grid;
  grid-template-columns: 1.15fr 0.9fr 1.35fr;
  gap: 12px;
  margin-top: 14px;
}

.insight-strip article {
  min-height: 88px;
  padding: 14px;
  border: 1px solid rgba(43, 109, 229, 0.12);
  border-radius: 8px;
  background: #f8fbff;
}

.insight-strip span {
  display: block;
  margin-bottom: 8px;
  color: var(--blue);
  font-size: 13px;
  font-weight: 800;
}

.insight-strip strong {
  display: block;
  color: #1f2937;
  font-size: 15px;
  line-height: 1.65;
}

/* ==================== METRIC STRIP ==================== */

.metric-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(140px, 100%), 1fr));
  gap: 1px;
  margin-bottom: 24px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}

.metric-strip .metric-cell {
  display: flex;
  min-width: 0;
  min-height: 82px;
  flex-direction: column;
  justify-content: center;
  padding: 12px 14px;
  background: var(--panel);
}

.metric-strip .metric-cell .metric-label {
  display: block;
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 500;
}

.metric-strip .metric-cell .metric-value {
  min-width: 0;
  font-size: clamp(16px, 1.35vw, 20px);
  font-weight: 700;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-variant-numeric: tabular-nums lining-nums;
  line-height: 1.25;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.metric-strip.metrics-7 {
  grid-template-columns: repeat(7, minmax(0, 1fr));
}

.metric-strip.metrics-4,
.metric-strip.four-col {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

/* ==================== SECTION DIVIDER ==================== */

.section-divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 28px 0 14px;
}

.section-divider:first-of-type {
  margin-top: 0;
}

.section-divider h2 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  flex-shrink: 0;
}

.section-divider .section-meta {
  font-size: 13px;
  color: var(--muted);
}

.section-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--line);
}

/* ==================== CHART ZONE ==================== */

.chart-zone {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.75fr);
  gap: 16px;
  margin-bottom: 24px;
}

.chart-zone > *,
.content-grid > *,
.content-grid.wide > *,
.backtest-grid > *,
.main-grid > *,
.detail-grid > * {
  min-width: 0;
}

.chart-panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  padding: 16px;
  box-shadow: var(--shadow-sm);
}

.data-panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  padding: 16px;
  box-shadow: var(--shadow-sm);
  min-width: 0;
  overflow: hidden;
}

/* ==================== TREND CHART ==================== */

.trend-chart {
  width: 100%;
  height: 380px;
  overflow: hidden;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.volume-chart {
  width: 100%;
  height: 100px;
  margin-top: 10px;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.chart-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-bottom: 8px;
  font-size: 13px;
  color: var(--muted);
}

.chart-legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.chart-legend span::before {
  content: "";
  width: 16px;
  height: 3px;
  border-radius: 999px;
  background: currentColor;
}

.chart-empty-state {
  display: grid;
  gap: 6px;
  margin-bottom: 10px;
  padding: 12px 14px;
  border: 1px dashed rgba(43, 109, 229, 0.28);
  border-radius: 6px;
  color: var(--muted);
  background: #f8fbff;
}

.chart-empty-state strong {
  color: var(--ink);
  font-size: 15px;
}

.chart-empty-state span {
  font-size: 13px;
  line-height: 1.6;
}

.legend-price { color: var(--ink); }
.legend-ma5 { color: var(--blue); }
.legend-ma10 { color: var(--gold); }
.legend-ma20 { color: var(--purple); }
.legend-ma60 { color: var(--teal); }

.chart-bg { fill: var(--surface-1); }

.chart-label {
  fill: var(--muted);
  font-size: 12px;
  paint-order: stroke;
  stroke: var(--surface-1);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}

.chart-price {
  text-anchor: end;
  dominant-baseline: central;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
}

.chart-date { text-anchor: middle; }

.axis {
  stroke: var(--line);
  stroke-width: 1.2;
}

.axis.muted { opacity: 0.5; }

.axis.grid {
  opacity: 0.4;
  stroke-dasharray: 2 3;
}

.equity-line {
  fill: none;
  stroke: var(--gold);
  stroke-width: 2.4;
  vector-effect: non-scaling-stroke;
}

.candle-up line,
.candle-up rect {
  fill: var(--red-fill);
  stroke: var(--red);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}

.candle-down line,
.candle-down rect {
  fill: var(--green-fill);
  stroke: var(--green);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}

.ma-line {
  fill: none;
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.ma5 { stroke: var(--blue); }
.ma10 { stroke: var(--gold); }
.ma20 { stroke: var(--purple); }
.ma60 { stroke: var(--teal); stroke-width: 1.8; }

.volume-up {
  fill: var(--volume-up-fill);
  stroke: var(--red);
  stroke-width: 0.5;
  vector-effect: non-scaling-stroke;
}

.volume-down {
  fill: var(--volume-down-fill);
  stroke: var(--green);
  stroke-width: 0.5;
  vector-effect: non-scaling-stroke;
}

/* ==================== PANEL HEADING ==================== */

.panel-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
  margin-bottom: 12px;
}

.panel-heading.compact {
  align-items: flex-start;
}

.panel-heading h2 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 700;
}

.panel-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.panel-heading .pill {
  flex-shrink: 0;
  padding: 3px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}

/* ==================== SIGNAL LIST ==================== */

.signal-list {
  display: grid;
  gap: 8px;
}

.signal-list .signal-item {
  padding: 12px;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.signal-list .signal-item.signal-up {
  border-color: color-mix(in srgb, var(--red) 28%, var(--line));
