        String(visibleBars[visibleBars.length - 1]?.date ?? '').slice(5) || '-',
      ]
    : ['-', '-', '-', '-', '-'];

  return (
    <div className="chart-panel">
      <div className="panel-heading">
        <div>
          <h2>K 线与量价结构</h2>
